effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmNoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(gmHash(i), gmHash(i + vec2(1.0, 0.0)), u.x),
             mix(gmHash(i + vec2(0.0, 1.0)), gmHash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float gmFbm(vec2 p){
  float total = 0.0, amp = 0.5;
  for (int i = 0; i < 5; i++){
    total += amp * gmNoise(p);
    p = p * 2.11 + 7.7;
    amp *= 0.5;
  }
  return total;
}
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec2 p = uv * scale + vec2(acTime * speed * 0.7, -acTime * speed);
  float n = gmFbm(p);
  float veins = 1.0 - abs(n * 2.0 - 1.0);
  veins = pow(smoothstep(0.34, 1.0, veins), 3.0);
  float pulse = 0.5 + 0.5 * sin(uv.y * 34.0 - acTime * speed * 5.0 + n * 7.0);
  float energy = clamp((veins * 0.92 + pulse * 0.22) * intensity, 0.0, 1.6);
  vec3 storm = mix(colorA.rgb, colorB.rgb, clamp(pulse * 0.7 + n, 0.0, 1.0)) * energy;
  vec3 screen = 1.0 - (1.0 - c) * (1.0 - clamp(storm, 0.0, 1.0));
  vec3 col = mix(c, screen, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * src.a, src.a);
}
